function ResearchWorkspace({api,disabled}:{api:(p:string,m?:string,b?:any)=>Promise<any>;disabled:boolean}){
 const [status,setStatus]=useState<any>(),[query,setQuery]=useState(''),[actor,setActor]=useState<'kevin'|'luisina'>('kevin'),[agreementChecked,setAgreementChecked]=useState(false),[confirmed,setConfirmed]=useState(false),[loading,setLoading]=useState(false),[savingAgreement,setSavingAgreement]=useState(false),[error,setError]=useState(''),[result,setResult]=useState<any>();
 const refresh=()=>api('/research/status').then(setStatus).catch((e:any)=>setError(e.message));useEffect(()=>{void refresh();},[]);
 const agreement=(accepted:boolean)=>{setSavingAgreement(true);setError('');void api('/research/agreement','POST',{actor,accepted}).then((r:any)=>{setStatus(r.status);setAgreementChecked(false);setConfirmed(false);}).catch((e:any)=>setError(e.message)).finally(()=>setSavingAgreement(false));};
 const submit=(event:FormEvent)=>{event.preventDefault();setLoading(true);setError('');void api('/research/search','POST',{actor,query,confirmPublicQuery:true}).then((r:any)=>{setResult(r);setStatus((s:any)=>({...s,count:r.usage.count}));setConfirmed(false);}).catch((e:any)=>setError(e.message)).finally(()=>setLoading(false));};
 const agreementFor=status?.agreements?.[actor];
 return <section className="panel"><h2>Investigación pública en Internet</h2><p>Estado: {!status?'consultando':status.enabled?'proveedor '+status.provider+' habilitado':'desactivada'}{status?.providerConfigured?` · ${status.count}/${status.monthlyLimit} consultas este mes · máximo local USD ${Number(status.maximumMonthlyCostUsd).toFixed(2)}`:''}</p><p>Al buscar, solo el texto escrito aquí se envía al proveedor externo. No incluyas nombres, direcciones, teléfonos ni información de la familia. La tarifa publicada usada por el límite es USD 0,005 por consulta; puede cambiar. Brave indica que puede retener consultas hasta 90 días. La aplicación no las guarda en su base de datos. <a href="https://api.search.brave.com/app/documentation/resources/help-feedback" target="_blank" rel="noreferrer">Precios</a> · <a href="https://api-dashboard.search.brave.com/documentation/resources/privacy-notice" target="_blank" rel="noreferrer">Privacidad</a>.</p>
  {!status?.providerConfigured&&<p>La búsqueda está apagada. Para habilitarla, la familia debe crear una cuenta Brave, activar un plan, revisar las condiciones y configurar `BRAVE_SEARCH_API_KEY` y `RESEARCH_PROVIDER=brave` en `.env`. No se ha hecho ninguna consulta.</p>}
  {status?.providerConfigured&&<section className="message"><h3>Acuerdo familiar de uso de resultados</h3><p>Brave exige que cada persona usuaria acepte obligaciones similares a sus términos de uso. Kevin y Luisina deben aceptar por separado. Al registrar tu aceptación, te comprometes a no guardar, cachear ni crear una base de datos de resultados; no redistribuirlos ni usarlos para entrenar, evaluar o mejorar modelos. La consulta requiere un consentimiento separado cada vez. <a href="https://api-dashboard.search.brave.com/documentation/resources/terms-of-service" target="_blank" rel="noreferrer">Leer términos completos</a>.</p><p>Kevin: {status.agreements?.kevin.accepted?`aceptó ${date(status.agreements.kevin.acceptedAt)}`:'pendiente'} · Luisina: {status.agreements?.luisina.accepted?`aceptó ${date(status.agreements.luisina.acceptedAt)}`:'pendiente'}</p><label>Persona que registra su propio acuerdo<select value={actor} onChange={e=>{setActor(e.target.value as 'kevin'|'luisina');setAgreementChecked(false);setConfirmed(false);}} disabled={disabled}><option value="kevin">Kevin</option><option value="luisina">Luisina</option></select></label>{agreementFor?.accepted?<button type="button" className="quiet" disabled={disabled||savingAgreement} onClick={()=>agreement(false)}>Revocar el acuerdo de {actor==='kevin'?'Kevin':'Luisina'}</button>:<><label className="check"><input type="checkbox" checked={agreementChecked} onChange={e=>setAgreementChecked(e.target.checked)} disabled={disabled||savingAgreement}/>Leí los términos y el aviso de privacidad; acepto estas obligaciones para mis propias consultas.</label><button type="button" disabled={disabled||savingAgreement||!agreementChecked} onClick={()=>agreement(true)}>Registrar aceptación de {actor==='kevin'?'Kevin':'Luisina'}</button></>}</section>}
  {error&&<p className="error" role="alert">{error}</p>}
  <form onSubmit={submit}><h3>Consulta de una fuente pública</h3><label>Consulta pública<input value={query} onChange={e=>setQuery(e.target.value)} minLength={3} maxLength={200} required placeholder="Regulación pública de garantías en Argentina" disabled={!status?.enabled||disabled}/></label><label>Quién consulta<select value={actor} onChange={e=>{setActor(e.target.value as 'kevin'|'luisina');setConfirmed(false);}} disabled={!status?.enabled||disabled}><option value="kevin">Kevin</option><option value="luisina">Luisina</option></select></label><label className="check"><input type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)} disabled={!status?.enabled||disabled}/>Confirmo que esta consulta es pública, no contiene datos familiares y autorizo enviarla al proveedor.</label><button disabled={!status?.enabled||disabled||!confirmed||loading}>{loading?'Buscando…':'Enviar consulta pública'}</button></form>
  {result&&<div><p>Proveedor: {result.provider} · consultado {date(result.fetchedAt)} · uso {result.usage.count}/{result.usage.monthlyLimit}</p>{result.sources.length?<ul>{result.sources.map((source:any,i:number)=><li key={`${source.url}-${i}`}><a href={source.url} target="_blank" rel="noreferrer">{source.title}</a><p>{source.snippet}</p><small>{source.pageAge??source.pageFetched??'Fecha de página no informada'}</small></li>)}</ul>:<p>Sin resultados públicos para esa consulta.</p>}</div>}
 </section>;
}
